package com.brainbot.indierecorder

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test
import java.math.BigInteger
import java.security.KeyFactory
import java.security.KeyPair
import java.security.spec.ECPrivateKeySpec

/** Test vectors made with the box's own code (recorder/vault.py): the phone must seal exactly like the PWA. */
class SealTest {
    private val box = Seal.BoxKey("874fe4c590148e18", Seal.unb64u("BMpzX_5tGtM8WxP7Ixp-nfkIVjJllYentZg6Hpv8-w7NRthYYr_72rLuSKHv7vYcKfexToVL-9IX_XrEibqDGm4"))
    private val clientId = "3f2b6c1e-9a7d-4e21-8c55-0b9f6a3d2e10"
    private val epk = "BBYLBhUVnrvff9SxGU1CsphsayzMrXmVIbizJikrZBmzk6IOEkrSpW7Op0-NroTY2R0PWsSjPyISJtFoHNElUso"
    private val pair: KeyPair = run {
        val pub = Seal.publicKey(Seal.unb64u(epk))
        val priv = KeyFactory.getInstance("EC").generatePrivate(
            ECPrivateKeySpec(BigInteger("0a1b2c3d4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f60718293a4b5c6d7e8f9", 16), pub.params))
        KeyPair(pub, priv)
    }
    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16).toByte() }

    @Test
    fun aRecordingsSealIsTheBoxs() {
        val start = Seal.start(box, clientId, pair)
        assertEquals(box.kid, start.kid)
        assertEquals(epk, start.epk)
        assertArrayEquals(hex("2138eeea3d84df87eee2b93f8cfd77fa1c3d874fffcbc92b6cabb09df8ffaf18"), start.key)
    }

    @Test
    fun chunksSealToTheBytesTheBoxOpens() {
        val key = Seal.start(box, clientId, pair).key
        assertArrayEquals(hex("eb6f4fe8d7a6c073953b4ca9a3b83b93f569bbabf115133a79f006c06966b8cc1c7992a666e2a9305b3e35"), Seal.seal(key, clientId, 0, hex("fff1696e6469652d7265636f72646572206368756e6b207a65726f")))
        assertArrayEquals(hex(""), Seal.seal(key, clientId, 1, hex("")))
        assertArrayEquals(hex(""), Seal.open(key, clientId, 1, hex("")))
    }

    @Test
    fun aChunkOpensOnlyAtItsPlace() {
        val key = Seal.start(box, clientId, pair).key
        val sealed = Seal.seal(key, clientId, 1, hex(""))
        assertThrows(Exception::class.java) { Seal.open(key, clientId, 2, sealed) }
        assertThrows(Exception::class.java) { Seal.open(key, "another-recording", 1, sealed) }
    }

    @Test
    fun eachRecordingGetsItsOwnKey() {
        val a = Seal.start(box, clientId)
        val b = Seal.start(box, clientId)
        assertEquals(65, Seal.unb64u(a.epk).size)
        assert(!a.key.contentEquals(b.key))
    }
}
